      "description": "Code, profile or rule revision label.",
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._+-]{0,63}$"
    },
    "safeRelativePath": {
      "description": "Relative POSIX path without empty, dot or dot-dot segments.",
      "type": "string",
      "maxLength": 255,
      "pattern": "^(?![A-Za-z0-9._/-]*(^|/)\\.{1,2}(/|$))[A-Za-z0-9._-]{1,128}(/[A-Za-z0-9._-]{1,128}){0,7}$"
    },
    "sourceFileRole": {
      "description": "Sealed source file role. source_manifest is the exact recording-source/v1 declaration bytes; its SHA-256 is the recording's sourceManifestSha256. The declaration lists every other sealed file and never itself.",
      "type": "string",
      "enum": [
        "source_mcap",
        "recorder_metadata",
        "calibration",
        "source_manifest"
      ]
    },
    "outputFileRole": {
      "type": "string",
      "enum": [
        "result_manifest",
        "clip_mp4",
        "hand_arrays_npz",
        "hand_observations_json",
        "frame_map_json",
        "thumbnail_jpeg",
        "viewer_rrd"
      ]
    },
    "jobKind": {
      "type": "string",
      "enum": ["process_recording", "export_release"]
    },
    "jobState": {
      "type": "string",
      "enum": [
        "queued",
        "submitting",
        "submit_unknown",
        "running",
        "result_pending",
        "succeeded",
        "failed",
        "cancel_requested",
        "cancelled",
        "needs_attention"
      ]
    },
    "raster": {
      "type": "object",
      "additionalProperties": false,
      "required": ["width", "height"],
      "properties": {
        "width": {
          "type": "integer",
          "minimum": 1,
          "maximum": 16384
        },
        "height": {
          "type": "integer",
          "minimum": 1,
          "maximum": 16384
        }
      }
    },
    "timeBase": {
      "description": "Rational time base: one PTS tick equals num/den seconds.",
      "type": "object",
      "additionalProperties": false,
      "required": ["num", "den"],
      "properties": {
        "num": {
          "type": "integer",
          "minimum": 1,
          "maximum": 2147483647
        },
        "den": {
          "type": "integer",
          "minimum": 1,
          "maximum": 2147483647
        }
      }
    },
    "sourceManifestSizeBytes": {
      "description": "Size of a source_manifest file: a control document of 1..1048576 bytes (the recording-source/v1 maxBytes).",
      "type": "string",
      "pattern": "^([1-9][0-9]{0,5}|10[0-3][0-9]{4}|104[0-7][0-9]{3}|1048[0-4][0-9]{2}|10485[0-6][0-9]|104857[0-6])$"
    },
    "signedUrl": {
      "description": "Short-lived http(s) bearer URL. Printable ASCII only (U+0021..U+007E): no whitespace, control or non-ASCII characters, so every regex engine agrees. Never log, persist or cache.",
      "type": "string",
      "minLength": 12,
      "maxLength": 4096,
      "pattern": "^https?://[!-~]+$"
    }
  }
}
''',
  "http/me.v1.schema.json": r'''
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://stateaction.ai/schemas/http/me.v1.json",
  "title": "Signed-in identity v1",
  "description": "GET /api/v1/me success data, carried as `data` inside http.success-envelope.v1. Identity comes from the server session; access status and roles come only from operator-managed server state, never from the client. `user.id` is the opaque Better Auth ID. `user.name` is untrusted display text. Active identities have at least one role; pending and disabled identities have none. Roles appear once each, in the canonical order collector, staff, customer.",
  "type": "object",
  "additionalProperties": false,
  "required": ["user", "access", "session"],
  "properties": {
    "user": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "email", "name"],
      "properties": {
        "id": {
          "$ref": "https://stateaction.ai/schemas/common.v1.json#/$defs/authUserId"
        },
        "email": {
          "description": "Sign-in email as stored by the identity provider; not re-validated as an address.",
          "type": "string",
          "maxLength": 320,
          "pattern": "^[^@]+@[^@]+$"
        },
        "name": {
          "description": "Untrusted display text (seed or Google profile). Render escaped; never an operator label.",
          "type": "string",
          "maxLength": 256
        }
      }
    },
    "access": {
      "type": "object",
      "additionalProperties": false,
      "required": ["status", "roles"],
      "properties": {
        "status": {
          "type": "string",
          "enum": ["active", "pending", "disabled"]
        },
        "roles": {
          "description": "Enabled roles, unique, in canonical order.",
          "type": "array",
          "maxItems": 3,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "enum": ["collector", "staff", "customer"]
          },
          "enum": [
            [],
            ["collector"],
            ["staff"],
            ["customer"],
            ["collector", "staff"],
            ["collector", "customer"],
            ["staff", "customer"],
            ["collector", "staff", "customer"]
          ]
        }
      },
      "if": {
        "required": ["status"],
        "properties": {
          "status": {
            "const": "active"
          }
        }
      },
      "then": {
        "properties": {
          "roles": {
            "type": "array",
            "minItems": 1,
            "maxItems": 3
          }
        }
      },
      "else": {
        "properties": {
          "roles": {
            "type": "array",
            "maxItems": 0
          }
        }
      }
    },
    "session": {
      "type": "object",
      "additionalProperties": false,
      "required": ["expiresAt"],
      "properties": {
        "expiresAt": {
          "$ref": "https://stateaction.ai/schemas/common.v1.json#/$defs/rfc3339Utc"
        }
      }
    }
  }
}
''',
